using Microsoft.Extensions.Diagnostics.HealthChecks;

namespace HealthCheckApi.HealthChecks;

/// <summary>
/// Reports unhealthy until the application has fully started.
/// Used by the liveness probe to avoid killing the app during startup.
/// </summary>
public class StartupHealthCheck : IHealthCheck
{
    private volatile bool _isReady;

    public bool IsReady
    {
        get => _isReady;
        set => _isReady = value;
    }

    public Task<HealthCheckResult> CheckHealthAsync(
        HealthCheckContext context, CancellationToken cancellationToken = default)
    {
        return Task.FromResult(_isReady
            ? HealthCheckResult.Healthy("Application has started.")
            : HealthCheckResult.Unhealthy("Application is still starting."));
    }
}

