using HealthCheckApi.HealthChecks;
using Microsoft.AspNetCore.Diagnostics.HealthChecks;
using Microsoft.Extensions.Diagnostics.HealthChecks;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddOpenApi();

// Register the startup health check as a singleton so its state is shared.
builder.Services.AddSingleton<StartupHealthCheck>();

builder.Services.AddHealthChecks()
    // Liveness: only checks that the process is alive and has finished starting.
    .AddCheck<StartupHealthCheck>(
        "startup",
        tags: ["live"])
    // Readiness: checks external dependencies the app needs to serve traffic.
    .AddSqlServer(
        connectionString: builder.Configuration.GetConnectionString("SqlServer")!,
        name: "sqlserver",
        failureStatus: HealthStatus.Unhealthy,
        tags: ["ready"])
    .AddRedis(
        redisConnectionString: builder.Configuration.GetConnectionString("Redis")!,
        name: "redis",
        failureStatus: HealthStatus.Unhealthy,
        tags: ["ready"]);

var app = builder.Build();

// Configure the HTTP request pipeline.
if (app.Environment.IsDevelopment())
{
    app.MapOpenApi();
}

// --- Kubernetes health-check endpoints ---

// Liveness probe: returns 200 once the app has started.
// K8s restarts the pod if this fails.
app.MapHealthChecks("/healthz/live", new HealthCheckOptions
{
    Predicate = check => check.Tags.Contains("live"),
    ResponseWriter = WriteMinimalResponse
});

// Readiness probe: returns 200 when DB + Redis are reachable.
// K8s stops sending traffic if this fails.
app.MapHealthChecks("/healthz/ready", new HealthCheckOptions
{
    Predicate = check => check.Tags.Contains("ready"),
    ResponseWriter = WriteMinimalResponse
});

// Mark the application as started.
var startupCheck = app.Services.GetRequiredService<StartupHealthCheck>();
startupCheck.IsReady = true;

var summaries = new[]
{
    "Freezing", "Bracing", "Chilly", "Cool", "Mild", "Warm", "Balmy", "Hot", "Sweltering", "Scorching"
};

app.MapGet("/weatherforecast", () =>
{
    var forecast = Enumerable.Range(1, 5).Select(index =>
        new WeatherForecast
        (
            DateOnly.FromDateTime(DateTime.Now.AddDays(index)),
            Random.Shared.Next(-20, 55),
            summaries[Random.Shared.Next(summaries.Length)]
        ))
        .ToArray();
    return forecast;
})
.WithName("GetWeatherForecast");

app.Run();

// Writes a compact JSON response for health check endpoints.
static Task WriteMinimalResponse(HttpContext context, HealthReport report)
{
    context.Response.ContentType = "application/json";

    var result = new
    {
        status = report.Status.ToString(),
        checks = report.Entries.Select(e => new
        {
            name = e.Key,
            status = e.Value.Status.ToString(),
            description = e.Value.Description,
            duration = e.Value.Duration.ToString()
        })
    };

    return context.Response.WriteAsJsonAsync(result);
}

record WeatherForecast(DateOnly Date, int TemperatureC, string? Summary)
{
    public int TemperatureF => 32 + (int)(TemperatureC / 0.5556);
}

