using Microsoft.AspNetCore.Diagnostics.HealthChecks;
using Microsoft.Extensions.Diagnostics.HealthChecks;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.

// Health checks: separate liveness (process alive) from readiness (dependencies available)
builder.Services.AddHealthChecks()
    // Liveness: only checks the process itself — never external dependencies
    .AddCheck("self", () => HealthCheckResult.Healthy(), tags: ["live"])
    // Readiness: checks external dependencies
    .AddSqlServer(
        connectionString: builder.Configuration.GetConnectionString("Database")!,
        name: "database",
        tags: ["ready"],
        timeout: TimeSpan.FromSeconds(5))
    .AddRedis(
        redisConnectionString: builder.Configuration.GetConnectionString("Redis")!,
        name: "redis",
        tags: ["ready"],
        timeout: TimeSpan.FromSeconds(5));

var app = builder.Build();

// Configure the HTTP request pipeline.

// Liveness: Kubernetes livenessProbe — failure restarts the pod
app.MapHealthChecks("/healthz/live", new HealthCheckOptions
{
    Predicate = check => check.Tags.Contains("live"),
    ResponseWriter = WriteMinimalResponse
}).AllowAnonymous();

// Readiness: Kubernetes readinessProbe — failure stops traffic to the pod
app.MapHealthChecks("/healthz/ready", new HealthCheckOptions
{
    Predicate = check => check.Tags.Contains("ready"),
    ResponseWriter = WriteDetailedResponse
}).AllowAnonymous();

// Startup: Kubernetes startupProbe — allows time for cold start
app.MapHealthChecks("/healthz/startup", new HealthCheckOptions
{
    Predicate = _ => true,
    ResponseWriter = WriteMinimalResponse
}).AllowAnonymous();

app.UseHttpsRedirection();

static Task WriteMinimalResponse(HttpContext context, HealthReport report)
{
    context.Response.ContentType = "application/json";
    return context.Response.WriteAsJsonAsync(new { status = report.Status.ToString() });
}

static Task WriteDetailedResponse(HttpContext context, HealthReport report)
{
    context.Response.ContentType = "application/json";
    var result = new
    {
        status = report.Status.ToString(),
        checks = report.Entries.Select(e => new
        {
            name = e.Key,
            status = e.Value.Status.ToString(),
            description = e.Value.Description,
            duration = e.Value.Duration.TotalMilliseconds
        })
    };
    return context.Response.WriteAsJsonAsync(result);
}

