using System.Diagnostics;
using System.Diagnostics.Metrics;
using OpenTelemetry.Metrics;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;

var builder = WebApplication.CreateBuilder(args);

// Define custom metrics for request latency and error tracking
var meter = new Meter("MyApi.Monitoring", "1.0.0");
var requestCounter = meter.CreateCounter<long>("myapi.requests.total", description: "Total number of requests");
var errorCounter = meter.CreateCounter<long>("myapi.errors.total", description: "Total number of errors");
var requestDuration = meter.CreateHistogram<double>("myapi.request.duration", unit: "ms", description: "Request duration in milliseconds");

// Configure OpenTelemetry
builder.Services.AddOpenTelemetry()
    .ConfigureResource(resource => resource.AddService(
        serviceName: "MyApi",
        serviceVersion: "1.0.0"))
    .WithTracing(tracing => tracing
        .AddAspNetCoreInstrumentation()
        .AddSource("MyApi.ActivitySource")
        .AddConsoleExporter())
    .WithMetrics(metrics => metrics
        .AddAspNetCoreInstrumentation()
        .AddMeter("MyApi.Monitoring")
        .AddConsoleExporter());

var app = builder.Build();

// Activity source for custom spans
var activitySource = new ActivitySource("MyApi.ActivitySource");

// Middleware to track request latency and errors
app.Use(async (context, next) =>
{
    var sw = Stopwatch.StartNew();
    try
    {
        await next();

        sw.Stop();
        var route = context.GetEndpoint()?.DisplayName ?? context.Request.Path;
        requestCounter.Add(1, new KeyValuePair<string, object?>("route", route),
                              new KeyValuePair<string, object?>("method", context.Request.Method),
                              new KeyValuePair<string, object?>("status", context.Response.StatusCode));
        requestDuration.Record(sw.Elapsed.TotalMilliseconds,
                              new KeyValuePair<string, object?>("route", route),
                              new KeyValuePair<string, object?>("method", context.Request.Method));

        if (context.Response.StatusCode >= 400)
        {
            errorCounter.Add(1, new KeyValuePair<string, object?>("route", route),
                                new KeyValuePair<string, object?>("status", context.Response.StatusCode));
        }
    }
    catch (Exception ex)
    {
        sw.Stop();
        errorCounter.Add(1, new KeyValuePair<string, object?>("exception", ex.GetType().Name));
        throw;
    }
});

// Sample endpoints
app.MapGet("/", () => "Hello World!");

app.MapGet("/api/items", () =>
{
    using var activity = activitySource.StartActivity("GetItems");
    activity?.SetTag("items.count", 3);
    return Results.Ok(new[] { "item1", "item2", "item3" });
});

app.MapGet("/api/items/{id:int}", (int id) =>
{
    using var activity = activitySource.StartActivity("GetItemById");
    activity?.SetTag("item.id", id);
    return id > 0 && id <= 3
        ? Results.Ok($"item{id}")
        : Results.NotFound();
});

app.MapGet("/api/slow", async () =>
{
    using var activity = activitySource.StartActivity("SlowOperation");
    await Task.Delay(500);
    return Results.Ok("completed");
});

app.Run();

